"use strict";(self.webpackChunknotes=self.webpackChunknotes||[]).push([["39"],{8386(e,n,i){i.r(n),i.d(n,{metadata:()=>t,default:()=>h,frontMatter:()=>a,contentTitle:()=>o,toc:()=>d,assets:()=>l});var t=JSON.parse('{"id":"DSA/DynamicProgramming/Form2/GridTraversal","title":"Grid Traversal","description":"Given a NxM grid, with walls denoted by \'#\', find the number of possible ways to travel from (0,0) to (N-1, M-1). If this were a shortest path finding problem, bfs could have easily solved it using the least time, however here we\'re asked to count the paths. Assume that the only possible moves are down, and right.","source":"@site/docs/DSA/DynamicProgramming/Form2/GridTraversal.md","sourceDirName":"DSA/DynamicProgramming/Form2","slug":"/DSA/DynamicProgramming/Form2/GridTraversal","permalink":"/Notes/DSA/DynamicProgramming/Form2/GridTraversal","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Grid Traversal"},"sidebar":"dsaSidebar","previous":{"title":"Distinct Substrings","permalink":"/Notes/DSA/DynamicProgramming/Form2/Substrings"},"next":{"title":"Longest Increasing Subsequence","permalink":"/Notes/DSA/DynamicProgramming/Form2/LIS"}}'),r=i(4848),s=i(8453);let a={title:"Grid Traversal"},o,l={},d=[{value:"Follow-up Questions:",id:"follow-up-questions",level:2}];function m(e){let n={br:"br",code:"code",em:"em",h2:"h2",img:"img",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(n.p,{children:["Given a NxM grid, with walls denoted by '#', find the number of possible ways to travel from (0,0) to (N-1, M-1). If this were a shortest path finding problem, bfs could have easily solved it using the least time, however here we're asked to count the paths. Assume that the only possible moves are down, and right.",(0,r.jsx)(n.br,{}),"\n",(0,r.jsx)(n.img,{alt:"alt text",src:i(716).A+"",width:"1080",height:"518"})]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Solution:"})," The DP state can be defined as, DP(i,j) = number of paths starting at (0,0) and ending at (i,j). The only paths that can converge at (i,j) are from (i-1,j) and (i,j-1) if they exist. This gives us the state transition, i.e. DP(i,j) = DP(i-1,j) + DP(i, j-1), if they exist and if they're not walls.  TC is O(N*M)."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-cpp",children:"int n,m;\ncin >> n;\nvector<string>arr;\narr.resize(n);\nfor(int i = 0; i < n;i++)cin >> arr[i];//take inputs\nm = arr[0].size(); \n\nint dp[1010][1010];\nmemset(dp, 0, sizeof(dp));\n\nfor(int i = 0; i < n;i++){\n    for(int j = 0; j <m;j++){\n        if(i == 0 && j ==0){\n            dp[i][j] = (arr[0][0] == '#') ? 0 : 1;\n        }\n        else if(arr[i][j] == '#'){\n            dp[i][j] = 0;\n        }else{\n            dp[i][j] = ((i-1)>=0 ?dp[i-1][j]:0) + ((j-1)>=0?dp[i][j-1]:0);\n        }\n    }\n}\n\nint ans = dp[n-1][m-1];\n"})}),"\n",(0,r.jsx)(n.p,{children:"Recursively:"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-cpp",children:"int rec(int i, int j){\n    if(arr[i][j] == '#')return 0;\n    if(i == 0 && j == 0){\n        return ((arr[0][0] == '#') ? 0 : 1);\n    }\n    int ans = 0;\n    if(i-1>= 0){\n        ans += rec(i-1,j);\n    }\n    if(j-1>= 0){\n        ans += rec(i,j-1);\n    }\n    return dp[i][j] = ans;\n}\n"})}),"\n",(0,r.jsx)(n.h2,{id:"follow-up-questions",children:"Follow-up Questions:"}),"\n",(0,r.jsxs)(n.ol,{children:["\n",(0,r.jsx)(n.li,{children:"Assume that you're given a grid of values assigned to each cell in the array, assuming you still start at (0,0) and end at (n-1,m-1), give the maximum sum of values you can obtain on your traversal."}),"\n",(0,r.jsx)(n.li,{children:"Given a grid of 1s and 0s fine the area of the maximum square containing only 1s."}),"\n",(0,r.jsx)(n.li,{children:"Given a grid of positive and negative numbers, a player starts from the cell (0,0) and optimally travels to (n-1,m-1) adding/removing health at cell according to the value present. Find the minimum health he needs to start with before entering cell (0,0)."}),"\n"]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Solution 1:"})," ",(0,r.jsx)(n.code,{children:"DP(i,j) "}),"= Max value accumumlated (0,0) through (i,j). Transition would be ",(0,r.jsx)(n.code,{children:"DP(i,j) = max(v[i-1][j] + DP(i-1,j), v[i][j-1]+DP(i,j-1))"})," if the cells exist."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-cpp",children:"int n,m; //assume n,m have been initialized and set\nint val[1010][1010];//assume values have been filled\nint dp[1010][1010];\nmemset(dp, 0,sizeof(dp));\n\nfor(int i = 0; i < n;i++){\n    for(int j = 0; j < m;j++){\n        if(i==0 && j == 0){\n            dp[i][j] = val[i][j];\n        }else{\n            dp[i][j] = max((i-1)>=0?dp[i-1][j]:0, (j-1)>=0?dp[i][j-1]:0);\n        }\n    }\n}\nint ans = dp[n-1][m-1];\n"})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Solution 2:"})," ",(0,r.jsx)(n.code,{children:"DP(i,j)"})," = length of the maximum square grid ending at ",(0,r.jsx)(n.code,{children:"(i,j)"}),". Transition: ",(0,r.jsx)(n.code,{children:"DP(i,j) = min(DP(i-1,j-1), DP(i-1,j), DP(i,j-1)) + 1"})," if all three neighbors exist and are non-zero."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-cpp",children:"int n,m;\nint arr[1010][1010];\nint dp[1010][1010];\nmemset(dp, 0, sizeof(dp));\nint ans = 0;\nfor(int i = 0; i < n;i++){\n    for(int j = 0; j < m;j++){\n        if(arr[i][j] == 0) continue;\n        if(i == 0 || j == 0){\n            dp[i][j] = 1;\n        }else{\n            dp[i][j] = min({dp[i-1][j-1], dp[i-1][j], dp[i][j-1]}) + 1;\n        }\n        ans = max(dp[i][j], ans);\n    }\n}\n"})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Note on Form Classification:"})," This problem is classified under Form 2 as the subproblem is defined as the optimal solution ending at ",(0,r.jsx)(n.code,{children:"(i,j)"}),", building up towards ",(0,r.jsx)(n.code,{children:"(n-1,m-1)"}),". However grid problems in general sit on the boundary between Form 2 and Form 3. The key distinction is \u2014 Form 3 involves two truly independent sequences where both indices carry meaningful separate information (like two strings in LCS), whereas here ",(0,r.jsx)(n.code,{children:"i"})," and ",(0,r.jsx)(n.code,{children:"j"})," together just describe a position in a single forward traversal (only down/right moves). Since both indices are forced in one direction and the grid is essentially a single path-finding structure, it leans Form 2. That said, the same problem could be reframed as Form 3 depending on how you define your subproblem \u2014 what matters more is that you recognize the transition pattern and arrive at the correct recurrence."]}),"\n",(0,r.jsxs)(n.p,{children:["**Solution 3: **",(0,r.jsx)(n.br,{}),"\n","Let DP(i,j) denote the minimum health needed before (0,0) to pass from (0,0) to (i,j) without dying. Now we've arrived at Node(i,j) from either (i-1,j) or (i,j-1), and if (i,j) is a positive health then coming into cell (i,j) player won't die, but if its negative, the minimum health at start needs to be nudged up by the abs value of that cell so that he can pass that cell. So DP(i,j) = min(DP(i-1,j), DP(i,j-1)) + abs(min(),arr[i][j])."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-cpp",children:"int arr[1010][1010];\nint dp[1010][1010];\nfor(int i = 0;i <n;i++){\n    for(int j = 0; j < m;j++){\n        if(i == 0 && j == 0){\n            if(arr[0][0] > 0)dp[0][0] = 1;\n            else dp[0][0] = abs(arr[0][0]) + 1;\n        }else{\n            if(arr[i][j] > 0)dp[i][j] = min((i-1)>= 0?dp[i-1][j]:0, (j-1)>=0?dp[i][j-1]:0);\n            else dp[i][j] = min((i-1)>= 0?dp[i-1][j]:0, (j-1)>=0?dp[i][j-1]:0) + abs(arr[i][j]) + 1;\n        }\n    }\n}\n\nint ans = dp[n-1][m-1];\n/***\nVerify if this approach is correct or wrong\n***/\n"})}),"\n",(0,r.jsxs)(n.p,{children:["Let DP(i,j) be the health needed before entering (i,j) to successfully reach (n-1,m-1). Let power needed before entering the next nodes be DP(i+1,j) and DP(i,j+1), so basically after leaving the (i,j)th cell we atleast need to have enough to go through the minimum of both the next cells, so DP(i,j) + arr[i][j] >= min(DP(i+1,j), DP(i,j+1)). This gives us DP(i,j) >= min(DP(i+1,j), DP(i,j+1)) - arr[i][j], if the RHS is negative, it means that arr[i][j] is sufficiently large for the least of the next two nodes, so we only need to be alive before entering so DP(i,j) = max(1, min(DP(i+1,j), DP(i,j+1)) - arr[i][j]), the base case being dp[0][0] = max(1, 1- arr[i][j]) O(N",(0,r.jsx)(n.em,{children:"M), can also binary search on all powers possible and that will be O(N"}),"M*log r)."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-cpp",children:"int dp[1010][1010];\ndp[n-1][m-1] = max(1, 1 - arr[n-1][m-1]);\nfor(int j = m-2; j >= 0; j--)\n    dp[n-1][j] = max(1, dp[n-1][j+1] - arr[n-1][j]);\nfor(int i = n-2; i >= 0; i--)\n    dp[i][m-1] = max(1, dp[i+1][m-1] - arr[i][m-1]);\nfor(int i = n-2; i >= 0; i--){\n    for(int j = m-2; j >= 0; j--){\n        int best = min(dp[i+1][j], dp[i][j+1]);\n        dp[i][j] = max(1, best - arr[i][j]);\n    }\n}\n\nint ans = dp[0][0];\n"})})]})}function h(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(m,{...e})}):m(e)}},716(e,n,i){i.d(n,{A:()=>t});let t=i.p+"assets/images/image-1-442d9e36d2bd8b5b607c0af89e754699.png"},8453(e,n,i){i.d(n,{R:()=>a,x:()=>o});var t=i(6540);let r={},s=t.createContext(r);function a(e){let n=t.useContext(s);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),t.createElement(s.Provider,{value:n},e.children)}}}]);